#!/bin/bash
# Uninstall script for kitty
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling kitty..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping kitty if running..."
pkill -f "kitty" 2>/dev/null || true

# Remove /Applications/kitty.app
echo "Removing /Applications/kitty.app..."
if [ -d "/Applications/kitty.app" ]; then
    rm -rf "/Applications/kitty.app" 2>/dev/null || true
elif [ -f "/Applications/kitty.app" ]; then
    rm -f "/Applications/kitty.app" 2>/dev/null || true
fi

# Remove $HOME/.config/kitty
echo "Removing $HOME/.config/kitty..."
if [ -d "$HOME/.config/kitty" ]; then
    rm -rf "$HOME/.config/kitty" 2>/dev/null || true
elif [ -f "$HOME/.config/kitty" ]; then
    rm -f "$HOME/.config/kitty" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/kitty
echo "Removing $HOME/Library/Caches/kitty..."
if [ -d "$HOME/Library/Caches/kitty" ]; then
    rm -rf "$HOME/Library/Caches/kitty" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/kitty" ]; then
    rm -f "$HOME/Library/Caches/kitty" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/kitty
echo "Removing $HOME/Library/Preferences/kitty..."
if [ -d "$HOME/Library/Preferences/kitty" ]; then
    rm -rf "$HOME/Library/Preferences/kitty" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/kitty" ]; then
    rm -f "$HOME/Library/Preferences/kitty" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/net.kovidgoyal.kitty.plist
echo "Removing $HOME/Library/Preferences/net.kovidgoyal.kitty.plist..."
if [ -d "$HOME/Library/Preferences/net.kovidgoyal.kitty.plist" ]; then
    rm -rf "$HOME/Library/Preferences/net.kovidgoyal.kitty.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/net.kovidgoyal.kitty.plist" ]; then
    rm -f "$HOME/Library/Preferences/net.kovidgoyal.kitty.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/net.kovidgoyal.kitty.savedState
echo "Removing $HOME/Library/Saved Application State/net.kovidgoyal.kitty.savedState..."
if [ -d "$HOME/Library/Saved Application State/net.kovidgoyal.kitty.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/net.kovidgoyal.kitty.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/net.kovidgoyal.kitty.savedState" ]; then
